 const reset=()=>{setQuery("");setDepartment("Tous");setProductType("Tous");setCustomerStatus("Tous")};
 const visibleIds=list.map((x:R)=>x.id),allVisible=visibleIds.length>0&&visibleIds.every((id:string)=>selectedIds.includes(id));
