function StopStatusControl({stop,customer,entry,mutate}:any){
 const update=async(status:string)=>{
  if(entry&&["En camion","Livré / posé"].includes(status)&&!window.confirm(entry.receivedQty>0?`Ce changement remet les ${stop.quantity} unité(s) hors du dépôt. Les ${entry.receivedQty} unité(s) déjà réceptionnées seront à nouveau déduites du stock. Confirmer ?`:"Clore ce retour et remettre la marchandise dans le circuit de livraison ? Le stock disponible reste inchangé."))return;
  await mutate("stop","update",{id:stop.id,data:{status}}).catch(()=>{});
 };
 const savStatus=normalizeSav(customer?.status)||normalizeSav(stop.savStatus)||"Aucun";
 return <div className="stop-status-controls"><label>Marchandise<select aria-label="Statut de la marchandise" value={stop.status} onChange={e=>update(e.target.value)}>{!stopStatuses.includes(stop.status)&&<option>{stop.status}</option>}{stopStatuses.map(status=><option key={status}>{status}</option>)}</select></label><label>SAV client<select aria-label="Statut SAV du client" value={savStatus} onChange={e=>mutate("customer","setSav",{id:stop.customerId,status:e.target.value}).catch(()=>{})}><option value="Aucun" disabled>Aucun SAV</option>{!savStatuses.includes(savStatus)&&savStatus!=="Aucun"&&<option>{savStatus}</option>}{savStatuses.map(status=><option key={status}>{status}</option>)}</select></label></div>
}
