 const title:R={receipt:"Nouvelle réception",product:selected?"Modifier le produit":"Nouveau produit",customer:selected?"Modifier le client":"Nouveau client",installer:selected?"Modifier l’installateur":"Nouvel installateur",route:selected?"Affecter ou modifier le bon de sortie":"Nouveau bon de sortie",stop:`Ajouter un client — ${selected?.number}`,stopEdit:"Modifier ou déplacer le client",upload:"Ajouter un document"};
