type ImportField="number"|"firstName"|"lastName"|"phone"|"email"|"address"|"postalCode"|"city"|"occupancyStatus"|"productType"|"taxReferenceIncome"|"taxNoticeReference"|"taxNumber"|"householdSize"|"preca"|"area"|"heatingType"|"hotWaterSystem"|"boilerLocation"|"phase"|"delegator"|"telepro"|"regie"|"status"|"comment";
const importFields:{key:ImportField;label:string;required?:boolean;aliases:string[]}[]=[
 {key:"number",label:"N° client",aliases:["numero client","n client","no client","id client","reference client","code client"]},
 {key:"firstName",label:"Prénom",required:true,aliases:["prenom","first name","firstname"]},
 {key:"lastName",label:"Nom",required:true,aliases:["nom","nom de famille","last name","lastname"]},
 {key:"phone",label:"Téléphone",aliases:["telephone","tel","mobile","portable"]},
 {key:"email",label:"E-mail",aliases:["email","e mail","mail","courriel"]},
 {key:"address",label:"Adresse complète",aliases:["adresse","adresse complete","adresse installation"]},
 {key:"postalCode",label:"Code postal",aliases:["code postal","cp","postal code","postcode"]},
 {key:"city",label:"Ville",aliases:["ville","city","commune"]},
 {key:"occupancyStatus",label:"Locataire ou propriétaire",aliases:["locataire ou proprietaire","occupation","statut occupation","occupant"]},
 {key:"productType",label:"Type de produit",aliases:["type de produit","produit","activite","activité"]},
 {key:"taxReferenceIncome",label:"Revenu fiscal de référence",aliases:["revenu fiscal de reference","rfr","revenu fiscal"]},
 {key:"taxNoticeReference",label:"Référence de l’avis",aliases:["reference avis","reference de l avis","reference de l avis d imposition"]},
 {key:"taxNumber",label:"Numéro fiscal",aliases:["numero fiscal","n fiscal","identifiant fiscal"]},
 {key:"householdSize",label:"Personnes dans le foyer",aliases:["nombre de personne dans le foyer","nombre de personnes dans le foyer","personnes foyer"]},
 {key:"area",label:"Surface habitable",aliases:["surface","surface habitable","surface m2","m2"]},
 {key:"preca",label:"Précarité",aliases:["precarite","couleur precarite","categorie precarite"]},
 {key:"heatingType",label:"Type de chauffage",aliases:["type de chauffage","chauffage"]},
 {key:"hotWaterSystem",label:"Eau chaude sanitaire",aliases:["eau chaude sanitaire","ecs","ballon ou chaudiere"]},
 {key:"boilerLocation",label:"Emplacement chaudière",aliases:["ou se situe la chaudiere","emplacement chaudiere","localisation chaudiere"]},
 {key:"phase",label:"Alimentation",aliases:["alimentation","phase","type alimentation"]},
 {key:"delegator",label:"Délégataire",aliases:["delegataire"]},
 {key:"telepro",label:"TELEPRO",aliases:["telepro","tele pro","teleprospecteur","teleoperateur"]},
 {key:"regie",label:"RÉGIE",aliases:["regie","regie commerciale"]},
 {key:"status",label:"Statut",aliases:["statut","statut client","statut dossier"]},
 {key:"comment",label:"Commentaire",aliases:["commentaire","notes","observation"]},
];
const normHeader=(value:unknown)=>String(value??"").normalize("NFD").replace(/[\u0300-\u036f]/g,"").toLowerCase().replace(/[^a-z0-9]+/g," ").trim();
function parseCsv(text:string){
 const first=(text.replace(/^\uFEFF/,"").split(/\r?\n/,1)[0]||""),candidates=[";",",","\t"],separator=candidates.sort((a,b)=>first.split(b).length-first.split(a).length)[0];
 const rows:string[][]=[];let row:string[]=[],cell="",quoted=false;
 for(let i=0;i<text.length;i++){const char=text[i];if(char==='"'){if(quoted&&text[i+1]==='"'){cell+='"';i++}else quoted=!quoted}else if(char===separator&&!quoted){row.push(cell.trim());cell=""}else if((char==='\n'||char==='\r')&&!quoted){if(char==='\r'&&text[i+1]==='\n')i++;row.push(cell.trim());if(row.some(Boolean))rows.push(row);row=[];cell=""}else cell+=char}
 row.push(cell.trim());if(row.some(Boolean))rows.push(row);return rows;
}
function CustomerImport({close,refresh}:{close:()=>void;refresh:(silent?:boolean)=>Promise<void>}){
 const [fileName,setFileName]=useState(""),[headers,setHeaders]=useState<string[]>([]),[rows,setRows]=useState<any[][]>([]),[mapping,setMapping]=useState<Partial<Record<ImportField,string>>>({}),[duplicateMode,setDuplicateMode]=useState<"skip"|"update">("skip"),[busy,setBusy]=useState(false),[err,setErr]=useState(""),[result,setResult]=useState<R|null>(null);
 const mapped=(row:any[])=>Object.fromEntries(importFields.map(field=>{const index=mapping[field.key];let value=index==null?"":row[Number(index)]??"";if(field.key==="phone"&&typeof value==="number"){const digits=String(Math.trunc(value));value=digits.length===9?`0${digits}`:digits}if(field.key==="preca"){const found=["Bleu","Jaune","Rose","Violet","Non applicable"].find(x=>normHeader(x)===normHeader(value));value=found||value}if(field.key==="occupancyStatus"){const found=["Propriétaire","Locataire"].find(x=>normHeader(x)===normHeader(value));value=found||value}if(field.key==="productType"){const found=["ITE","PV","PAC"].find(x=>normHeader(x)===normHeader(value));value=found||value}if(field.key==="hotWaterSystem"){const found=["Ballon","Chaudière"].find(x=>normHeader(x)===normHeader(value));value=found||value}if(field.key==="phase"){const found=["Monophasé","Triphasé"].find(x=>normHeader(x)===normHeader(value));value=found||value}if(field.key==="status"){const found=customerStatuses.find(x=>normHeader(x)===normHeader(value));value=found||value}return[field.key,String(value??"").trim()]}));
 const chooseMapping=(head:string[])=>{const next:Partial<Record<ImportField,string>>={};for(const field of importFields){const index=head.findIndex(h=>field.aliases.includes(normHeader(h)));if(index>=0)next[field.key]=String(index)}setMapping(next)};
 const pickFile=async(file?:File)=>{if(!file)return;setErr("");setResult(null);setBusy(true);try{if(file.size>10_000_000)throw Error("Le fichier dépasse 10 Mo.");let matrix:any[][];if(file.name.toLowerCase().endsWith(".csv")){matrix=parseCsv(await file.text())}else if(file.name.toLowerCase().endsWith(".xlsx")){const {readSheet}=await import("read-excel-file/browser");matrix=await readSheet(file) as any[][]}else throw Error("Choisissez un fichier .xlsx ou .csv.");if(matrix.length<2)throw Error("Le fichier ne contient aucune ligne client.");if(matrix.length>5001)throw Error("L’import est limité à 5 000 clients par fichier.");const head=matrix[0].map(x=>String(x??"").trim());if(!head.some(Boolean))throw Error("La première ligne doit contenir les noms des colonnes.");setFileName(file.name);setHeaders(head);setRows(matrix.slice(1).filter(row=>row.some(cell=>String(cell??"").trim())));chooseMapping(head)}catch(e:any){setFileName("");setHeaders([]);setRows([]);setErr(e.message)}finally{setBusy(false)}};
 const downloadTemplate=()=>{const content="N° client;Prénom;Nom;Téléphone;E-mail;Adresse complète;Code postal;Locataire ou propriétaire;Type de produit;Revenu fiscal de référence;Référence de l’avis;Numéro fiscal;Nombre de personnes dans le foyer;Précarité;Surface habitable;Type de chauffage;Eau chaude sanitaire;Emplacement chaudière;Alimentation;Délégataire;TELEPRO;RÉGIE;Statut;Commentaire\nCL-0001;Jean;Dupont;0612345678;jean.dupont@exemple.fr;12 rue des Fleurs;75001;Propriétaire;PAC;24500;REF-AVIS;1234567890123;4;Bleu;110;Gaz;Chaudière;Garage;Monophasé;Délégataire exemple;Téléprospecteur exemple;Régie exemple;Devis à envoyer;Commentaire dossier\n",url=URL.createObjectURL(new Blob(["\uFEFF"+content],{type:"text/csv;charset=utf-8"})),a=document.createElement("a");a.href=url;a.download="modele-import-clients-fleuron.csv";a.click();URL.revokeObjectURL(url)};
 const submit=async()=>{setErr("");if(mapping.firstName==null||mapping.lastName==null){setErr("Associez obligatoirement les colonnes Prénom et Nom.");return}const records=rows.map(mapped).filter(x=>Object.values(x).some(Boolean));if(!records.length){setErr("Aucun client exploitable dans ce fichier.");return}setBusy(true);try{const response=await fetch("/api/customers/import",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({records,duplicateMode})}),json=await response.json() as R;if(!response.ok)throw Error(json.error);setResult(json);await refresh(true)}catch(e:any){setErr(e.message)}finally{setBusy(false)}};
 return <Dialog open onOpenChange={open=>!open&&close()}><DialogContent className="entry-dialog import-dialog"><DialogHeader><DialogTitle>Importer des clients</DialogTitle></DialogHeader>{result?<div className="import-result"><CheckCircle2/><h3>Import terminé</h3><div><span><b>{result.inserted}</b>Nouveaux clients</span><span><b>{result.updated}</b>Clients actualisés</span><span><b>{result.skipped}</b>Doublons ignorés</span><span><b>{result.errors?.length||0}</b>Lignes en erreur</span></div>{result.errors?.length>0&&<ul>{result.errors.slice(0,8).map((x:R)=><li key={`${x.line}-${x.message}`}>Ligne {x.line} : {x.message}</li>)}</ul>}<Button className="gold" onClick={close}>Fermer</Button></div>:<div className="import-flow"><section className="import-drop"><FileUp/><div><b>Déposez votre liste clients</b><span>Fichier Excel .xlsx ou CSV · 5 000 clients maximum</span></div><label><input type="file" accept=".xlsx,.csv" onChange={e=>pickFile(e.target.files?.[0])}/>{fileName?"Changer de fichier":"Choisir un fichier"}</label><button onClick={downloadTemplate}><Download/> Télécharger un modèle CSV</button></section>{fileName&&<><div className="import-file"><CheckCircle2/><div><b>{fileName}</b><span>{rows.length} ligne{rows.length>1?"s":""} détectée{rows.length>1?"s":""}</span></div></div><section className="mapping"><header><div><b>Correspondance des colonnes</b><span>Vérifiez où chaque information doit être rangée.</span></div></header><div>{importFields.map(field=><Field key={field.key} l={`${field.label}${field.required?" *":""}`}><select value={mapping[field.key]??""} onChange={e=>setMapping(current=>({...current,[field.key]:e.target.value||undefined}))}><option value="">Ne pas importer</option>{headers.map((header,index)=><option key={`${header}-${index}`} value={index}>{header||`Colonne ${index+1}`}</option>)}</select></Field>)}</div></section><section className="import-preview"><b>Aperçu</b><div className="table-wrap"><table><thead><tr><th>Client</th><th>Téléphone</th><th>Adresse</th></tr></thead><tbody>{rows.slice(0,4).map((row,index)=>{const x:any=mapped(row);return <tr key={index}><td><b>{x.firstName||"—"} {x.lastName||"—"}</b><small>{x.number||"Sans numéro"}</small></td><td>{x.phone||"—"}<small>{x.email}</small></td><td>{x.address||"—"}<small>{x.postalCode?`Code postal : ${x.postalCode}`:""}</small></td></tr>})}</tbody></table></div></section><Field l="Si un client existe déjà"><select value={duplicateMode} onChange={e=>setDuplicateMode(e.target.value as "skip"|"update")}><option value="skip">Ne pas le modifier</option><option value="update">Actualiser sa fiche avec le fichier</option></select></Field></>}{err&&<p className="form-error">{err}</p>}<footer><Button variant="outline" onClick={close}>Annuler</Button><Button className="gold" disabled={!rows.length||busy} onClick={submit}>{busy?<><RefreshCw className="spin"/> Traitement…</>:<>Importer {rows.length||""} client{rows.length>1?"s":""}</>}</Button></footer></div>}</DialogContent></Dialog>
}

