 const latestStop=stops.find((s:R)=>s.status!=="Annulé"),latestRoute=d.routes.find((r:R)=>r.id===latestStop?.routeId),installer=d.installers.find((i:R)=>i.id===(customer?.assignedInstallerId||latestRoute?.installerId||latestStop?.installerId)),team=teamsOf(installer).find(t=>t.id===(customer?.assignedTeamId||latestRoute?.teamId)),material=d.products.find((p:R)=>p.id===customer?.materialProductId);
