 const normalize=(value:any)=>String(value||"").normalize("NFD").replace(/[\u0300-\u036f]/g,"").toLocaleLowerCase("fr-FR").replace(/\s+/g," ").trim(),needle=normalize(name),matches=rows.filter((x:R)=>{const first=normalize(x.firstName),last=normalize(x.lastName);return needle&&(needle===normalize(`${first} ${last}`)||needle===normalize(`${last} ${first}`)||needle===last||needle===normalize(x.number))}),customer=matches.length===1?matches[0]:null;
